{
  "name": "iOS 26 Age Calculator",
  "description": "A sleek, glassmorphic age calculator with an iOS 26 aesthetic.",
  "requestFramePermissions": []
}

/**
 * iOS 26 Age Calculator Logic
 * Handles the calculation of age based on a birthdate input.
 */

document.addEventListener('DOMContentLoaded', () => {
    const calculateBtn = document.getElementById('calculateBtn');
    const dobInput = document.getElementById('dob') as HTMLInputElement;
    const resultArea = document.getElementById('resultArea');

    const yearEl = document.getElementById('years');
    const monthEl = document.getElementById('months');
    const dayEl = document.getElementById('days');
    const nextBdayEl = document.getElementById('nextBirthdayText');

    // Set max date to today
    const today = new Date();
    const todayStr = today.toISOString().split('T')[0];
    dobInput.setAttribute('max', todayStr);

    const calculateAge = () => {
        const birthDateValue = dobInput.value;
        if (!birthDateValue) {
            alert('Please select a valid date of birth');
            return;
        }

        const birthDate = new Date(birthDateValue);
        const now = new Date();

        let years = now.getFullYear() - birthDate.getFullYear();
        let months = now.getMonth() - birthDate.getMonth();
        let days = now.getDate() - birthDate.getDate();

        // Adjust for negative months or days
        if (days < 0) {
            months--;
            // Get last day of previous month
            const prevMonthLastDay = new Date(now.getFullYear(), now.getMonth(), 0).getDate();
            days += prevMonthLastDay;
        }

        if (months < 0) {
            years--;
            months += 12;
        }

        // Animate results
        if (resultArea) resultArea.classList.remove('show');

        setTimeout(() => {
            if (yearEl) yearEl.textContent = years.toString();
            if (monthEl) monthEl.textContent = months.toString();
            if (dayEl) dayEl.textContent = days.toString();

            if (resultArea) resultArea.classList.add('show');

            // Calculate Next Birthday
            const nextBirthday = new Date(now.getFullYear(), birthDate.getMonth(), birthDate.getDate());
            if (nextBirthday < now) {
                nextBirthday.setFullYear(now.getFullYear() + 1);
            }

            const diffTime = Math.abs(nextBirthday.getTime() - now.getTime());
            const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

            if (nextBdayEl) {
                if (diffDays === 0 || (birthDate.getMonth() === now.getMonth() && birthDate.getDate() === now.getDate())) {
                    nextBdayEl.innerHTML = "🎂 Happy Birthday! It's your special day!";
                } else {
                    nextBdayEl.textContent = `Next birthday in ${diffDays} days`;
                }
            }
        }, 100);
    };

    if (calculateBtn) {
        calculateBtn.addEventListener('click', calculateAge);
    }

    // Allow Enter key to calculate
    dobInput.addEventListener('keypress', (e) => {
        if (e.key === 'Enter') {
            calculateAge();
        }
    });
});

