/**
 * iOS 26 Age Calculator Logic
 * Cleaned version focusing solely on age identity features.
 */

document.addEventListener('DOMContentLoaded', () => {
    const dobInput = document.getElementById('dob') as HTMLInputElement;
    const calculateBtn = document.getElementById('calculateBtn');
    const resultsContainer = document.getElementById('results');
    const yearsEl = document.getElementById('years');
    const monthsEl = document.getElementById('months');
    const daysEl = document.getElementById('days');
    const nextBdayEl = document.getElementById('nextBirthday');

    // Prevent future dates
    const today = new Date();
    dobInput.max = today.toISOString().split('T')[0];

    const runCalculation = () => {
        const birthValue = dobInput.value;
        if (!birthValue) {
            triggerShake(dobInput);
            return;
        }

        const birthDate = new Date(birthValue);
        const now = new Date();

        // Basic Difference
        let y = now.getFullYear() - birthDate.getFullYear();
        let m = now.getMonth() - birthDate.getMonth();
        let d = now.getDate() - birthDate.getDate();

        // Adjustment Logic
        if (d < 0) {
            m--;
            const lastMonth = new Date(now.getFullYear(), now.getMonth(), 0).getDate();
            d += lastMonth;
        }

        if (m < 0) {
            y--;
            m += 12;
        }

        // Apply with animation
        if (resultsContainer) resultsContainer.classList.remove('active');

        setTimeout(() => {
            if (yearsEl) yearsEl.textContent = y.toString();
            if (monthsEl) monthsEl.textContent = m.toString();
            if (daysEl) daysEl.textContent = d.toString();

            if (resultsContainer) resultsContainer.classList.add('active');

            // Calculate Countdown to Next Birthday
            const currentYearBday = new Date(now.getFullYear(), birthDate.getMonth(), birthDate.getDate());
            if (currentYearBday < now && 
                !(now.getMonth() === birthDate.getMonth() && now.getDate() === birthDate.getDate())) {
                currentYearBday.setFullYear(now.getFullYear() + 1);
            }

            const diff = currentYearBday.getTime() - now.getTime();
            const daysToBday = Math.ceil(diff / (1000 * 60 * 60 * 24));

            if (nextBdayEl) {
                if (daysToBday <= 0) {
                    nextBdayEl.innerHTML = "✨ <b>Happy Birthday!</b> Today is the day.";
                } else {
                    nextBdayEl.textContent = `Next birthday in ${daysToBday} days`;
                }
            }
        }, 150);
    };

    const triggerShake = (el: HTMLElement) => {
        el.style.transform = 'translateX(-10px)';
        setTimeout(() => el.style.transform = 'translateX(10px)', 50);
        setTimeout(() => el.style.transform = 'translateX(-10px)', 100);
        setTimeout(() => el.style.transform = 'translateX(0)', 150);
        el.style.borderColor = '#FF3B30';
        setTimeout(() => el.style.borderColor = '', 1000);
    };

    if (calculateBtn) calculateBtn.addEventListener('click', runCalculation);

    // Quick Enter Key support
    dobInput.addEventListener('keydown', (e) => {
        if (e.key === 'Enter') runCalculation();
    });
});

/* iOS 26 Core Theme System */
:root {
    --ios26-primary: #00f2fe;
    --ios26-secondary: #4facfe;
    --ios26-dark: #020024;
}

body.theme-ios26 {
    background: var(--ios26-dark);
}

